<template>
  <WorkShell title="مركز القيادة المؤسسية" subtitle="تشغيل حي • تحليلات • تكاملات • ذكاء مساعد" :nav-items="navItems" :breadcrumbs="breadcrumbs" :has-data="true" @refresh="refreshAll">
    <template #toolbar><WorkToolbar><template #center><WorkTabs v-model="activeTab" :tabs="tabs" variant="pills" aria-label="مركز القيادة" /></template></WorkToolbar></template>
    <section class="hero"><div><span class="eyebrow"><FeatherIcon name="activity" :size="15"/> تشغيل حي</span><h2>مركز القيادة المؤسسية</h2><p>طبقة تشغيل موحّدة تربط البيع والمخزون والمالية والتكاملات والذكاء المساعد.</p></div><div class="actions"><button class="btn primary" type="button" @click="refreshAll"><FeatherIcon name="refresh-cw" :size="16"/> تحديث الآن</button><router-link class="btn" :to="{name:'POSSale'}"><FeatherIcon name="shopping-cart" :size="16"/> بيع جديد</router-link></div></section>
    <div v-if="error" class="error" role="alert">{{ error }}</div>
    <section v-if="activeTab==='overview'" class="kpis"><article v-for="k in kpis" :key="k.key" class="kpi"><FeatherIcon :name="k.icon" :size="18"/><div><small>{{k.label}}</small><strong>{{k.value}}</strong><em>{{k.note}}</em></div></article></section>
    <section v-if="activeTab==='overview'" class="grid"><article class="panel wide"><header><div><h3>الإيرادات الحية</h3><small>تحديث تلقائي كل 30 ثانية</small></div><b class="live">● LIVE</b></header><div class="chart"><canvas ref="canvas" aria-label="رسم الإيرادات"></canvas></div></article><article class="panel"><header><h3>أعلى المنتجات</h3></header><div v-for="(p,i) in overview.topProducts||[]" :key="p.product_id||i" class="rank"><b>{{i+1}}</b><span>{{p.product_name||p.product_id}}</span><strong>{{money(p.revenue)}}</strong></div><div v-if="!overview.topProducts?.length" class="empty">لا توجد بيانات كافية.</div></article></section>
    <section v-if="activeTab==='integrations'" class="panel"><header><div><h3>مركز التكاملات</h3><small>الحالة الفعلية للموصلات المسجلة — بدون ادعاء دعم غير منفذ</small></div></header><div class="providers"><article v-for="p in providers" :key="p.key" class="provider"><FeatherIcon :name="p.icon||'link'" :size="19"/><strong>{{p.name}}</strong><small>{{(p.modes||[]).join(' • ')}}</small><span class="badge" :class="{ready:p.configured}">{{p.configured?'مهيأ':'غير مهيأ'}}</span></article></div><div v-if="!integrations.length" class="empty">لا توجد موصلات مهيأة لهذا المستأجر.</div><div v-for="item in integrations" :key="item.id" class="connection integration-row"><div><strong>{{item.name}}</strong><small>{{item.adapter}} • {{item.base_url}}</small></div><span>{{item.is_active?'فعال':'متوقف'}}</span><button v-if="item.adapter_meta?.implemented" class="btn" type="button" :disabled="testing===item.id" @click="testIntegration(item)">{{testing===item.id?'اختبار…':'اختبار الاتصال'}}</button><span v-else class="muted">المحول غير منفذ</span></div><p v-if="message" class="notice">{{message}}</p></section>
    <section v-if="activeTab==='ai'" class="panel"><header><div><h3>المساعد الذكي</h3><small>مزود قابل للتبديل عبر مركز التكاملات</small></div></header><div class="ai"><textarea v-model="prompt" rows="3" placeholder="اسأل عن المبيعات، المخزون، الربحية أو اقترح إجراءً." @keydown.ctrl.enter.prevent="ask"/><button class="btn primary" :disabled="busy||!prompt.trim()" @click="ask">{{busy?'جارٍ التحليل…':'حلّل'}}</button></div><div v-if="answer" class="answer">{{answer}}</div></section>
    <section v-if="activeTab==='fiscal'" class="panel"><header><div><h3>الزكاة والضريبة / الفوترة الإلكترونية</h3><small>حالة الموصل فقط؛ لا يُعلن الامتثال تلقائيًا</small></div></header><div class="state" :class="{ok:fiscal.configured}"><FeatherIcon :name="fiscal.configured?'check-circle':'alert-circle'" :size="20"/><strong>{{fiscal.configured?'موصل مهيأ':'غير مهيأ'}}</strong><span>{{fiscal.configured?'جاهز للاختبار والتهيئة':'اربط موصل ZATCA من التكاملات'}}</span></div><div v-for="c in fiscal.connections||[]" :key="c.id" class="connection"><strong>{{c.name}}</strong><small>{{c.base_url}}</small><span>{{c.active?'فعال':'متوقف'}}</span></div></section>
  </WorkShell>
</template>
<script setup>
import {computed,nextTick,onBeforeUnmount,onMounted,ref} from "vue"
import Chart from "chart.js/auto"
import {FeatherIcon} from "dypos-ui"
import WorkShell from "@/components/work/WorkShell.vue"
import WorkToolbar from "@/components/work/WorkToolbar.vue"
import WorkTabs from "@/components/work/WorkTabs.vue"
import {getEnterpriseOverview,getIntegrationCatalog,getConfiguredIntegrations,getZatcaStatus,askEnterpriseAI,testEnterpriseIntegration,formatMetric} from "@/services/enterprise-hub"
const activeTab=ref("overview"),overview=ref({kpis:{},series:[],topProducts:[]}),providers=ref([]),integrations=ref([]),fiscal=ref({configured:false,connections:[]}),error=ref(""),message=ref(""),prompt=ref(""),answer=ref(""),busy=ref(false),testing=ref(""),canvas=ref(null)
let chart=null,timer=null
const tabs=[{id:"overview",label:"التشغيل الحي",icon:"activity"},{id:"integrations",label:"التكاملات",icon:"link"},{id:"ai",label:"الذكاء",icon:"cpu"},{id:"fiscal",label:"الزكاة والضريبة",icon:"file-check"}]
const navItems=[{id:"pos",label:"نقطة البيع",to:{name:"POSSale"},icon:"shopping-cart"},{id:"reports",label:"التقارير",to:{name:"Reports"},icon:"bar-chart-2"},{id:"stock",label:"المخزون",to:{name:"StockManagement"},icon:"package"},{id:"control",label:"مركز القيادة",to:{name:"EnterpriseControlCenter"},icon:"activity"}]
const breadcrumbs=[{label:"الرئيسية",to:{name:"POSSale"}},{label:"مركز القيادة",current:true}]
const kpis=computed(()=>{const k=overview.value.kpis||{};return[{key:"orders",label:"العمليات",value:formatMetric(k.orders),note:"اليوم",icon:"layers"},{key:"gross",label:"الإيراد",value:formatMetric(k.gross,2),note:"إجمالي",icon:"trending-up"},{key:"ticket",label:"متوسط السلة",value:formatMetric(k.avgTicket,2),note:"لكل عملية",icon:"shopping-bag"},{key:"low",label:"منخفض المخزون",value:formatMetric(k.lowStock),note:"تنبيه",icon:"alert-triangle"},{key:"queue",label:"طابور التكاملات",value:formatMetric(k.integrationQueue),note:"قيد التنفيذ",icon:"refresh-cw"},{key:"dead",label:"حالات متوقفة",value:formatMetric(k.integrationDead),note:"تحتاج تدخل",icon:"shield-off"}]})
const money=v=>formatMetric(v,2)
async function draw(){await nextTick();if(!canvas.value)return;if(chart)chart.destroy();chart=new Chart(canvas.value,{type:"line",data:{labels:(overview.value.series||[]).map(x=>x.day),datasets:[{label:"الإيراد",data:(overview.value.series||[]).map(x=>Number(x.gross)||0),tension:.25,fill:true}]},options:{responsive:true,maintainAspectRatio:false,interaction:{mode:"index",intersect:false},plugins:{legend:{display:false}},scales:{y:{beginAtZero:true}}}})}
async function refreshAll(){error.value="";try{const [o,c,i,z]=await Promise.all([getEnterpriseOverview(),getIntegrationCatalog(),getConfiguredIntegrations(),getZatcaStatus()]);overview.value=o;integrations.value=i.integrations||[];providers.value=(c.providers||[]).map(p=>({...p,icon:({zatca:"file-check",shopify:"shopping-bag",woocommerce:"shopping-cart",salla:"store",zid:"store",whatsapp:"message-circle",sms:"smartphone",email:"mail",telegram:"send",openai:"cpu",azure_ai:"cloud",generic_webhook:"link"})[p.key]||"link",configured:integrations.value.some(x=>x.adapter===p.key)}));fiscal.value=z;await draw()}catch(e){error.value=e?.message||"تعذر تحديث مركز القيادة"}}
async function testIntegration(item){testing.value=item.id;message.value="";try{const r=await testEnterpriseIntegration(item.id);message.value=item.name+" — "+(r.ok?"الاتصال ناجح":"فشل الاتصال")+" • "+r.latency_ms+"ms • "+(r.detail||"")}catch(e){message.value=e?.message||"تعذر اختبار التكامل"}finally{testing.value=""}}
async function ask(){if(!prompt.value.trim())return;busy.value=true;answer.value="";try{answer.value=(await askEnterpriseAI(prompt.value)).answer||"لم يصل رد."}catch(e){answer.value=e?.message||"تعذر تشغيل المساعد"}finally{busy.value=false}}
onMounted(()=>{void refreshAll();timer=setInterval(()=>void refreshAll(),30000)})
onBeforeUnmount(()=>{if(timer)clearInterval(timer);if(chart)chart.destroy()})
</script>
<style scoped>
.hero,.panel,.kpi{border:1px solid var(--dy-border);background:var(--dy-surface);border-radius:16px}.hero{display:flex;justify-content:space-between;gap:20px;padding:22px;margin-bottom:14px;background:linear-gradient(120deg,var(--dy-primary-soft),var(--dy-bg-sunken))}.hero h2{margin:8px 0 4px}.hero p,small,em{color:var(--dy-text-muted)}.eyebrow,.live{color:var(--dy-primary);font-weight:800}.actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.btn{display:inline-flex;align-items:center;gap:7px;min-height:40px;padding:0 13px;border:1px solid var(--dy-border-strong);border-radius:10px;background:var(--dy-surface);color:var(--dy-text);text-decoration:none;font-weight:700;cursor:pointer}.primary{background:var(--dy-primary);border-color:var(--dy-primary);color:var(--dy-primary-contrast)}.error,.notice{padding:12px;border-radius:10px;margin:12px 0;background:var(--dy-warning-soft)}.kpis{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:10px;margin-bottom:14px}.kpi{display:flex;gap:10px;padding:13px}.kpi div{display:grid}.kpi strong{font-size:17px}.kpi em{font-size:10px;font-style:normal}.grid{display:grid;grid-template-columns:2fr 1fr;gap:14px}.panel{padding:16px;margin-bottom:14px}.panel header{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:14px}.panel h3{margin:0;font-size:15px}.chart{height:300px}.rank{display:grid;grid-template-columns:24px 1fr auto;gap:8px;padding:9px;border-bottom:1px solid var(--dy-border)}.rank span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.providers{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.provider{display:grid;grid-template-columns:auto 1fr auto;gap:5px 9px;padding:13px;text-align:start;border:1px solid var(--dy-border);border-radius:12px;background:var(--dy-bg-sunken);color:var(--dy-text)}.provider small{grid-column:2}.badge{font-size:11px;padding:3px 7px;border-radius:999px;background:var(--dy-warning-soft)}.badge.ready{background:var(--dy-success-soft)}.integration-row{grid-template-columns:1fr auto auto}.muted{color:var(--dy-text-muted)}.ai{display:grid;grid-template-columns:1fr auto;gap:10px}.ai textarea{width:100%;padding:12px;border:1px solid var(--dy-border-strong);border-radius:10px;background:var(--dy-bg);color:var(--dy-text);font:inherit}.answer{margin-top:12px;padding:14px;background:var(--dy-bg-sunken);border-radius:10px;white-space:pre-wrap;line-height:1.8}.state{display:flex;align-items:center;gap:9px;padding:14px;border-radius:11px;background:var(--dy-warning-soft)}.state.ok{background:var(--dy-success-soft)}.connection{display:grid;grid-template-columns:1fr 2fr auto;gap:10px;padding:10px;border-bottom:1px solid var(--dy-border)}@media(max-width:1100px){.kpis{grid-template-columns:repeat(3,1fr)}.grid{grid-template-columns:1fr}.providers{grid-template-columns:repeat(2,1fr)}}@media(max-width:700px){.hero{flex-direction:column}.kpis{grid-template-columns:repeat(2,1fr)}.providers{grid-template-columns:1fr}.ai{grid-template-columns:1fr}.chart{height:240px}}
</style>